export interface JobConfig {
  /** Controls what and how to inspect for findings. */
  inspectJob?: Job_InspectDetails_RequestedOptions_JobConfig | Computed<Job_InspectDetails_RequestedOptions_JobConfig>;
  /** The job id can contain uppercase and lowercase letters, numbers, and hyphens; that is, it must match the regular expression: `[a-zA-Z\d-_]+`. The maximum length is 100 characters. Can be empty to allow the system to generate one. */
  jobId?: string | Computed<string>;
  /** Deprecated. This field has no effect. */
  locationId?: string | Computed<string>;
  /** Configuration for a risk analysis job. See https://docs.cloud.google.com/sensitive-data-protection/docs/concepts-risk-analysis to learn more. */
  riskJob?: Job_RiskDetails_RequestedOptions_JobConfig | Computed<Job_RiskDetails_RequestedOptions_JobConfig>;
}

export interface JobAttrs {
  /** Output only. Events that should occur after the job has completed. */
  actionDetails: Job_ActionDetails[];
  /** Output only. Time when the job was created. */
  createTime: string;
  /** Output only. Time when the job finished. */
  endTime: string;
  /** Output only. A stream of errors encountered running the job. */
  errors: Job_Errors[];
  /** The results of an inspect DataSource job. */
  inspectDetails: Job_InspectDetails;
  /** Controls what and how to inspect for findings. */
  inspectJob: Job_InspectDetails_RequestedOptions_JobConfig;
  /** The job id can contain uppercase and lowercase letters, numbers, and hyphens; that is, it must match the regular expression: `[a-zA-Z\d-_]+`. The maximum length is 100 characters. Can be empty to allow the system to generate one. */
  jobId: string;
  /** Output only. If created by a job trigger, the resource name of the trigger that instantiated the job. */
  jobTriggerName: string;
  /** Output only. Time when the job was last modified by the system. */
  lastModified: string;
  /** Deprecated. This field has no effect. */
  locationId: string;
  /** Output only. The server-assigned name. */
  name: string;
  /** Result of a risk analysis operation request. */
  riskDetails: Job_RiskDetails;
  /** Configuration for a risk analysis job. See https://docs.cloud.google.com/sensitive-data-protection/docs/concepts-risk-analysis to learn more. */
  riskJob: Job_RiskDetails_RequestedOptions_JobConfig;
  /** Output only. Time when the job started. */
  startTime: string;
  /** Output only. State of a job. */
  state: string;
  /** The type of job. */
  type: string;
}

